package me.tenai.blackchinhighlighter;

import javax.inject.Inject;

import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

import java.awt.*;

/*
 * Credits:
 *
 * https://github.com/MoreBuchus/buchus-plugins/blob/tzhaar-hp-tracker/src/main/java/com/tzhaarhptracker/TzhaarHPTrackerOverlay.java
 * For the highlighting code
 *
 */

public class BlackChinHighlightOverlay extends Overlay {
    private final BlackChinHighlighterPlugin plugin;
    private final BlackChinHighlighterConfig config;
    private final Client client;
    private final ModelOutlineRenderer modelOutlineRenderer;

    @Inject
    private BlackChinHighlightOverlay(BlackChinHighlighterPlugin plugin, BlackChinHighlighterConfig config,
                                      Client client, ModelOutlineRenderer modelOutlineRenderer)
    {
        this.plugin = plugin;
        this.config = config;
        this.client = client;
        this.modelOutlineRenderer = modelOutlineRenderer;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(Overlay.PRIORITY_HIGHEST);
        setLayer(OverlayLayer.UNDER_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        WorldView wv = client.getTopLevelWorldView();

        if(plugin.isCalibrating()) {
            var loadedNpcs = wv.npcs();
            for(var npc : loadedNpcs) {
                if(npc.isDead()) continue;
                if(plugin.getNpcs().contains(npc)) continue;
                if(npc.getName().equals("Black chinchompa")) {
                    NPCComposition npcComposition = npc.getTransformedComposition();
                    if(npcComposition != null) {
                        Shape hull = npc.getConvexHull();
                        if (hull != null) {
                            renderPoly(graphics, new Color(0, 255, 0, 255), new Color(0, 0, 0, 0), hull, config.highlightOutlineWidth());
                        }

                    }
                }
            }
        }

        for(var npc : plugin.getNpcs()) {
            if(npc.isDead()) continue;
            if(!config.highlightFourthChinchompa() && npc.getIndex() == plugin.getFourthSpawnIndex()) continue;

            Color outlineColor = config.highlightOutlineColor();
            Color fillColor = config.highlightFillColor();

            if(plugin.getDyingNpcs().containsKey(npc) && config.recolorDeadChinchompas()) {
                outlineColor = config.highlightOutlineColorDead();
                fillColor = config.highlightFillColorDead();
            }
            NPCComposition npcComposition = npc.getTransformedComposition();
            if (npcComposition != null) {
                if(config.highlightStyle().contains(BlackChinHighlighterConfig.HighlightStyle.HULL)) {
                    Shape hull = npc.getConvexHull();
                    if (hull != null) {
                        renderPoly(graphics, outlineColor, fillColor, hull, config.highlightOutlineWidth());
                    }
                }

                if(config.highlightStyle().contains(BlackChinHighlighterConfig.HighlightStyle.TILE)) {
                    LocalPoint lp = npc.getLocalLocation();

                    if (lp != null) {
                        Polygon tilePoly = Perspective.getCanvasTileAreaPoly(client, lp, 1);
                        if(tilePoly != null) {
                            renderPoly(graphics, outlineColor, fillColor, tilePoly, config.highlightOutlineWidth());
                        }
                    }
                }

                if(config.highlightStyle().contains(BlackChinHighlighterConfig.HighlightStyle.TRUE_TILE)) {
                    LocalPoint lp = LocalPoint.fromWorld(wv, npc.getWorldLocation());

                    if (lp != null) {
                        lp = new LocalPoint(lp.getX() + 128 / 2 - 64, lp.getY() + 128 / 2 - 64, wv);
                        Polygon tilePoly = Perspective.getCanvasTileAreaPoly(client, lp, 1);
                        if(tilePoly != null) {
                            renderPoly(graphics, outlineColor, fillColor, tilePoly, config.highlightOutlineWidth());
                        }
                    }
                }

                if(config.highlightStyle().contains(BlackChinHighlighterConfig.HighlightStyle.OUTLINE)) {
                    modelOutlineRenderer.drawOutline(npc, (int) config.highlightOutlineWidth(), outlineColor, 4);
                }
            }
        }
        return null;
    }

    private void renderPoly(Graphics2D g, Color outlineColor, Color fillColor, Shape polygon, double width)
    {
        if (polygon != null)
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setColor(outlineColor);
            g.setStroke(new BasicStroke((float) width));
            g.draw(polygon);
            g.setColor(fillColor);
            g.fill(polygon);
        }
    }
}

package me.tenai.blackchinhighlighter;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import java.awt.*;
import java.util.Set;

/*
* Credits:
*
* https://github.com/MoreBuchus/buchus-plugins/blob/tzhaar-hp-tracker/src/main/java/com/tzhaarhptracker/TzhaarHPTrackerConfig.java
* For the highlight style enum
*
*/

@ConfigGroup("Black Chinchompa Highlighter")
public interface BlackChinHighlighterConfig extends Config
{
    @ConfigItem(
            position = 1,
            keyName = "highlightStyle",
            name = "Highlight Style",
            description = "Picks the highlight style you want for the chinchompas"
    )
    default Set<HighlightStyle> highlightStyle()
    {
        return Set.of(HighlightStyle.HULL);
    }
    @Alpha
    @ConfigItem(
            position = 2,
            keyName = "outlineColor",
            name = "Outline Color",
            description = "Outline color for the highlighted chinchompas"
    )
    default Color highlightOutlineColor()
    {
        return new Color(255, 255, 255, 255);
    }

    @Alpha
    @ConfigItem(
            position = 3,
            keyName = "fillColor",
            name = "Fill Color",
            description = "Fill color for the highlighted chinchompas"
    )
    default Color highlightFillColor()
    {
        return new Color(255, 255, 255, 64);
    }

    @Alpha
    @ConfigItem(
            position = 4,
            keyName = "outlineColorDead",
            name = "Fill Color",
            description = "Outline color for the dying chinchompas"
    )
    default Color highlightOutlineColorDead()
    {
        return new Color(255, 0, 0, 255);
    }

    @Alpha
    @ConfigItem(
            position = 5,
            keyName = "fillColorDead",
            name = "Fill Color",
            description = "Fill color for the dying chinchompas"
    )
    default Color highlightFillColorDead()
    {
        return new Color(255, 0, 0, 64);
    }

    @ConfigItem(
            position = 6,
            keyName = "outlineWidth",
            name = "Outline Width",
            description = "Outline width for the highlighted chinchompas"
    )
    default double highlightOutlineWidth() {
        return 2.0;
    }

    @ConfigItem(
            position = 7,
            keyName = "recolorDeadChins",
            name = "Recolor Dying Chinchompas",
            description = "Changes the color for Chinchompas that will die soon (after being shot). May be somewhat buggy but errors should correct themselves."
    )
    default boolean recolorDeadChinchompas() { return true; }

    @ConfigItem(
            position = 8,
            keyName = "highlightFourthChinchompa",
            name = "Highlight North West Spawn",
            description = "Highlights the North West Chinchompa, this is the only one that isn't insta-lured, so it's optional to kill and it's usually better to prioritize the other three Chinchompas."
    )
    default boolean highlightFourthChinchompa() { return false; }

    @Getter
    @RequiredArgsConstructor
    enum HighlightStyle
    {
        TILE("Tile"),
        TRUE_TILE("True Tile"),
        HULL("Hull"),
        OUTLINE("Outline");

        @Getter
        private final String group;

        @Override
        public String toString()
        {
            return group;
        }
    }
}

package me.tenai.blackchinhighlighter;

import net.runelite.api.Client;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.*;

public class BlackChinHighlighterPanel extends PluginPanel {
    BlackChinHighlighterPlugin plugin;
    Client client;

    @Inject
    BlackChinHighlighterPanel(BlackChinHighlighterPlugin plugin, Client client) {
        this.plugin = plugin;
        this.client = client;
    }

    void Init() {
        getParent().setLayout(new BorderLayout());
        getParent().add(this, BorderLayout.CENTER);

        setLayout(new BorderLayout());
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        setBackground(ColorScheme.DARKER_GRAY_COLOR);

        JPanel container = new JPanel();
        container.setLayout(new BorderLayout());
        container.setBackground(ColorScheme.DARKER_GRAY_COLOR);

        JButton button = new JButton("Recalibrate");
        button.setBackground(ColorScheme.DARK_GRAY_COLOR);
        button.addActionListener(e -> plugin.recalibrate());

        JPanel frame = new JPanel();
        frame.add(button);
        frame.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        container.add(frame, BorderLayout.CENTER);

        JLabel calibrationLabel = new JLabel("<html><center><h1>Black Chinchompa Highlighter</h1><p><strong>Instructions</strong></p></Center>To use this plugin, go to the Black Chinchompa area and begin shooting the marked Chinchompas until the plugin detects the four spawns. You will need to do this at the beginning of every session, but it should persist on log-outs and server hops. If the Chinchompas are highlighted incorrectly, see the next section.<br><br><center><p><strong>Recalibration</strong></p></center>Pressing the button will require you to recalibrate which Chinchompas to highlight, but if a Chinchompa is being highlighted incorrectly pressing this should fix it.<br><br></center></html>");
        add(calibrationLabel, BorderLayout.PAGE_START);
        add(container, BorderLayout.CENTER);
    }
}

package me.tenai.blackchinhighlighter;

import com.google.inject.Provides;
import javax.inject.Inject;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

import java.awt.image.BufferedImage;
import java.util.*;

@Slf4j
@PluginDescriptor(
	name = "Black Chinchompa Highlighter"
)
public class BlackChinHighlighterPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private BlackChinHighlighterConfig config;

	@Inject
	private BlackChinHighlightOverlay highlightOverlay;

	@Inject
	private CalibrationOverlay calibrationOverlay;

	@Inject
	private OverlayManager overlayManager;

	@Getter
	private boolean calibrated = false;

	@Getter
	private boolean calibrating = false;

	private final ArrayList<WorldPoint> coordinateList = new ArrayList<>(Arrays.asList(
			new WorldPoint(3139, 3780, 0),
			new WorldPoint(3136, 3782, 0),
			new WorldPoint(3140, 3784, 0),
			new WorldPoint(3134, 3786, 0) /* fourth spawn */
	));

	private HashSet<Integer> removedNpcIndexes = new HashSet<>();

	@Getter
	private HashSet<Integer> npcIndexes = new HashSet<>();

	@Getter
	private int fourthSpawnIndex = 0;

	@Getter
	private HashSet<NPC> npcs = new HashSet<>();

	/* contains tick count to auto-remove false positives */
	@Getter
	private HashMap<NPC, Integer> dyingNpcs = new HashMap<>();

	@Inject
	private ClientToolbar clientToolbar;

	private BlackChinHighlighterPanel panel;
	private NavigationButton navButton;

	@Subscribe
	private void onNpcSpawned(NpcSpawned event) {
		var npc = event.getNpc();
		if (calibrating && (npc.getName() != null)) {
			if(npc.getName().equals("Black chinchompa") &&
				coordinateList.contains(npc.getWorldLocation()) &&
				removedNpcIndexes.contains(npc.getIndex())
			) {
				if (npc.getWorldLocation().equals(new WorldPoint(3134, 3786, 0))) {
					fourthSpawnIndex = npc.getIndex();
				}

				npcIndexes.add(npc.getIndex());
				if (npcIndexes.size() >= 4) {
					calibrated = true;
					calibrating = false;
				}
			}
		}
		if (npcIndexes.contains(npc.getIndex())) {
			npcs.add(npc);
		}
	}

	@Subscribe
	private void onNpcDespawned(NpcDespawned e) {
		npcs.removeIf(n -> n.getIndex() == e.getNpc().getIndex());
		dyingNpcs.remove(e.getNpc());
		if(calibrating) {
			removedNpcIndexes.add(e.getNpc().getIndex());
		}
	}

	@Subscribe
	private void onGameTick(GameTick event) {
		if(!calibrated) {
			var chinArea = new WorldArea(3125, 3765, 25, 30, 0);
			var playerLocation = client.getLocalPlayer().getWorldLocation();
			if(playerLocation.isInArea(chinArea)) {
				overlayManager.add(calibrationOverlay);
				calibrating = true;
			} else {
				overlayManager.remove(calibrationOverlay);
				calibrating = false;
			}
		}
		/* apparently doing it this way is necessary to do removals mid-iteration... I hate java */
		Iterator<Map.Entry<NPC, Integer>> it = dyingNpcs.entrySet().iterator();

		while (it.hasNext()) {
			var entry = it.next();
			var currentTickCount = entry.getValue();

			if(currentTickCount > 5) {
				it.remove();
				continue;
			}

			entry.setValue(currentTickCount + 1);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged xpDrop) {
		processXpDrop(xpDrop.getSkill());
	}

	@Subscribe
	public void onFakeXpDrop(FakeXpDrop xpDrop) {
		processXpDrop(xpDrop.getSkill()); /* can't test since I don't have any 200m combat stats */
	}

	/* Credit for this https://github.com/vikke1234/raids-death-indicator/blob/master/src/main/java/com/example/utils/DamageHandler.java */

	private void processXpDrop(Skill skill) {
		if(skill == Skill.HITPOINTS) { /* all attacks should give hitpoints xp */
			Player player = client.getLocalPlayer();
			Actor entity = player.getInteracting();

			if(!(entity instanceof NPC)) {
				return;
			}

			NPC npc = (NPC) entity;

			if(npcs.contains(npc)) {
				dyingNpcs.put(npc, 0);
			}
		}
	}

	@Subscribe
	private void onGameStateChanged(GameStateChanged event) {
		npcs.clear();
	}

	public void recalibrate() {
		npcIndexes.clear();
		npcs.clear();

		calibrated = false;
		calibrating = false;
	}

	@Override
	protected void startUp() throws Exception
	{
		panel = injector.getInstance(BlackChinHighlighterPanel.class);
		panel.Init();

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/blackchin.png");

		navButton = NavigationButton.builder()
				.tooltip("Black Chinchompa Highlighter")
				.icon(icon)
				.priority(6)
				.panel(panel)
				.build();

		clientToolbar.addNavigation(navButton);

		npcIndexes.clear();
		npcs.clear();
		overlayManager.add(highlightOverlay);
		overlayManager.add(calibrationOverlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		npcIndexes.clear();
		npcs.clear();
		overlayManager.remove(highlightOverlay);
		overlayManager.remove(calibrationOverlay);

		clientToolbar.removeNavigation(navButton);

		calibrated = false;
		calibrating = false;
	}

	@Provides
	BlackChinHighlighterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BlackChinHighlighterConfig.class);
	}
}

package me.tenai.blackchinhighlighter;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

import javax.inject.Inject;
import java.awt.*;

public class CalibrationOverlay extends OverlayPanel {
    private final BlackChinHighlighterPlugin plugin;
    private Long startTime;

    @Inject
    CalibrationOverlay(BlackChinHighlighterPlugin plugin) {
        this.plugin = plugin;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        panelComponent.getChildren().clear();

        int calibratedChins = plugin.getNpcIndexes().size();

        panelComponent.getChildren().add(LineComponent.builder()
                .left(String.format("Chinchompas %d / 4", calibratedChins))
                .build()
        );

        setPosition(OverlayPosition.TOP_LEFT);

        if(calibratedChins == 0) panelComponent.setBackgroundColor(new Color(255, 0, 0, 64));
        else if (calibratedChins < 4) panelComponent.setBackgroundColor(new Color(255, 128, 0, 64));
        else {
            panelComponent.setBackgroundColor(new Color(0, 255, 0, 64));
        }

        if(plugin.isCalibrated()) {
            if(startTime == null) startTime = System.currentTimeMillis();
            long timeSinceStart = System.currentTimeMillis() - startTime;
            if(timeSinceStart > 5000) return null;
        } else {
            startTime = null;
        }

        return panelComponent.render(graphics);
    }
}

